import data from "./data/bmc-wards.json" with { type: "json" };
import { boundsOf, multiPolygonContains, type MultiPolygon } from "./polygon";
import { distanceMetres } from "./geohash";

/**
 * The 24 BMC administrative wards, with real boundaries.
 *
 * Generated by `scripts/geo-wards.mts` from DataMeet's open data (CC BY-SA 2.5 India);
 * the attribution travels with the data and is shown wherever the boundaries are drawn.
 *
 * Codes are `MCGM-<letter>` (Municipal Corporation of Greater Mumbai), the value
 * `items.ward_code`, `intakes.ward_code` and `wards.code` join on.
 */

export interface WardGeo {
  code: string;
  letter: string;
  name: string;
  areaKm2: number;
  centroid: { latitude: number; longitude: number };
  boundary: MultiPolygon;
}

export const WARD_SOURCE = {
  source: data.source,
  attribution: data.attribution,
  license: data.license,
  city: data.city,
} as const;

export const WARDS: WardGeo[] = data.wards as WardGeo[];

const BOXES = WARDS.map((ward) => ({ ward, box: boundsOf(ward.boundary) }));

/** Everything the map should frame: the union of ward boxes. */
export const CITY_BOUNDS = (() => {
  const all = BOXES.map((b) => b.box);
  return {
    south: Math.min(...all.map((b) => b.south)),
    west: Math.min(...all.map((b) => b.west)),
    north: Math.max(...all.map((b) => b.north)),
    east: Math.max(...all.map((b) => b.east)),
  };
})();

export function wardByCode(code: string | null | undefined): WardGeo | undefined {
  return code ? WARDS.find((ward) => ward.code === code) : undefined;
}

/**
 * The ward a point falls in, by boundary — or, within `snapMetres` of the city, the
 * nearest ward centroid. A GPS fix on the shoreline or a creek can land a few metres
 * outside a simplified outline; that is still a Mumbai pickup. A fix 20 km away is not,
 * and returns `null` rather than being filed somewhere it never happened.
 */
export function wardForPoint(latitude: number, longitude: number, snapMetres = 1_500): WardGeo | null {
  for (const { ward, box } of BOXES) {
    if (latitude < box.south || latitude > box.north || longitude < box.west || longitude > box.east) continue;
    if (multiPolygonContains(ward.boundary, latitude, longitude)) return ward;
  }
  let best: WardGeo | null = null;
  let bestDistance = Infinity;
  for (const ward of WARDS) {
    const d = distanceMetres({ latitude, longitude }, ward.centroid);
    if (d < bestDistance) {
      bestDistance = d;
      best = ward;
    }
  }
  // Centroid distance overstates edge distance, so the allowance is generous: half the
  // ward's own size on top of the snap distance.
  if (!best) return null;
  const halfSpan = Math.sqrt(best.areaKm2) * 500;
  return bestDistance <= halfSpan + snapMetres ? best : null;
}
